import {uid,dayKey,offsetDate,initialState,publicPlan,copyTemplate,validMilestones,templates,dueLifestyle} from './model.mjs';
const $=(s,r=document)=>r.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const app=$('#app'),dialog=$('#dialog');
let state=initialState(),db=null,toastTimer,planTab='mine',visionTab='board',visionMode='view',diaryFilter='all',savedType='all',selectedGrowth='',growthHorizon='1 month',currentDraft=null,visionDraft=null,mediaRecorder=null,audioChunks=[],soundscapeTimer=null;
const labels={today:'Today',overview:'Goals',goals:'Plans',lifestyle:'Lifestyle',vision:'Vision',reflect:'Room to Grow',diary:'Reflections',saved:'Saved',explore:'Explore',profile:'Profile'};
const categories=['Personal','Fitness','Learning','Career','Travel','Wellbeing','Movement','Home','Connection','Relationships','Hygiene','Money','Creativity'];
const valueChoices=['Confidence','Health','Consistency','Freedom','Connection','Kindness','Growth','Curiosity','Creativity','Independence','Balance','Adventure','Self-respect','Security','Calm'];
