const svg=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.goals}</svg>`;
const horizons=['1 month','3 months','6 months','1 year','2 years'];
const photoNames={gym:'Gym & movement',study:'Study & career',travel:'Travel & adventure',home:'Home & balance'};
const action=(name,id='')=>`data-action="${name}" data-id="${esc(id)}"`;
const option=(v,c,l=v)=>`<option value="${esc(v)}" ${v===c?'selected':''}>${esc(l)}</option>`;
const dateLabel=d=>d?new Date(d+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'When I get there';
const timeLabel=t=>{if(!t)return 'Set reminder';const [h,m]=t.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'}`};
const route=()=>Object.hasOwn(labels,location.hash.slice(1))?location.hash.slice(1):'today';
const complete=id=>Boolean(state.completed[dayKey()]?.[id]);
const completionMode=(date,id)=>{const value=state.completed?.[date]?.[id];return value===true?'full':value||''};
const reminderOff=id=>Boolean(state.reminderSilenced?.[dayKey()]?.[id]);
const findHabit=id=>state.lifestyle.flatMap(r=>r.habits||[r]).find(h=>h.id===id)||state.plans.flatMap(p=>p.habits).find(h=>h.id===id);
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3800)}
function heading(k,t,d,b=''){return `<div class="page-heading page-${route()}"><div><span class="eyebrow">${k}</span><h1>${t}</h1><p class="subtitle">${d}</p></div>${b}</div>`}
function showDialog(html,wide=false,label='YOUR NEXT MOVE'){let shade=$('#dialog-shade');if(!shade){shade=document.createElement('div');shade.id='dialog-shade';document.body.append(shade);shade.onclick=()=>dialog.close()}shade.hidden=false;$('.dialog-top .eyebrow',dialog).textContent=label;$('#dialog-content').innerHTML=html;dialog.classList.toggle('wide-dialog',wide);if(!dialog.open)dialog.show();dialog.scrollTop=0}
function error(form,message){const el=$('.form-error',form);el.textContent=message;el.focus()}
function updateStatus(text){$('#save-status').textContent=text}
async function save(message){if(db){try{await new Promise((resolve,reject)=>{const tx=db.transaction('data','readwrite');tx.objectStore('data').put(structuredClone(state),'state');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)});updateStatus('Beta · saved on this device');if(message)toast(message);return true}catch{updateStatus('Changes not saved');toast('Device storage is full or unavailable. Keep this page open; your latest changes are not saved.');return false}}updateStatus('Beta · this session only');toast('Device storage is unavailable. Changes last until this page closes.');return false}
async function load(){try{db=await new Promise((resolve,reject)=>{const req=indexedDB.open('glow-getter-prototype',1);req.onupgradeneeded=()=>req.result.createObjectStore('data');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});const saved=await new Promise((resolve,reject)=>{const req=db.transaction('data').objectStore('data').get('state');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});if(saved?.version===2&&Array.isArray(saved.plans)&&Array.isArray(saved.board))state=saved;state.reminderSilenced??={};state.someday??=[];state.affirmationSets??=[{id:uid(),name:'Stepping into my power',affirmations:['I trust the version of me I am becoming.','I move with confidence, clarity, and purpose.','I am allowed to take up space.'],visibility:'public',habitIds:[]},{id:uid(),name:'Soft mornings',affirmations:['I can begin again without rushing.','Peace belongs in my routine.'],visibility:'private',habitIds:[]}];state.savedPlans??=[];state.journal??=[];state.archivedBoards??=[];state.visionBoardMeta??={id:'current-board',name:'My vision board',visibility:'private'};state.visionBoardMeta.background??='paper';state.archivedAffirmations??=[];state.archivedDreams??=[];state.quotes??=[];state.savedItems??=[];state.settings??={darkMode:false};state.settings.themeChosen??=false;state.community??={name:'Your name',bio:'Building my next chapter.'};state.community.name??='Your name';state.community.bio??='Building my next chapter.';state.community.profilePhoto??='';if(!state.visionSeparated){const separated=[];for(const item of state.board){const base={...item,text:'',sticker:'none'};if(item.kind==='photo')separated.push(base);if(item.text)separated.push({...item,id:uid(),kind:'text',image:'',src:'',sticker:'none',size:'normal'});if(item.sticker&&item.sticker!=='none')separated.push({...item,id:uid(),kind:'graphic',image:'',src:'',text:'',size:'normal'});if(item.kind!=='photo'&&!item.text&&(!item.sticker||item.sticker==='none'))separated.push(item)}state.board=separated;state.visionSeparated=true}for(const tile of state.board){if(tile.text==='Keep that motion.')tile.text='Stay in motion.'}
const layout={photo:[[1,3],[43,7],[62,39],[3,55],[48,67],[20,80]],text:[[55,3],[5,34],[53,42],[25,61],[47,78],[3,87]],graphic:[[71,22],[35,48],[5,72],[73,81],[39,88]],affirmation:[[28,20],[55,58]]},counts={photo:0,text:0,graphic:0,affirmation:0};for(const tile of state.board){const kind=layout[tile.kind]?tile.kind:'text',spots=layout[kind],n=counts[kind]++;if(!Number.isFinite(Number(tile.x)))tile.x=spots[n%spots.length][0];if(!Number.isFinite(Number(tile.y)))tile.y=spots[n%spots.length][1];tile.z??=n+1;}for(const ritual of state.lifestyle){if(!Array.isArray(ritual.habits))ritual.habits=[{id:ritual.id,full:ritual.full||ritual.name,light:ritual.light||ritual.full||ritual.name,reminder:ritual.reminder||''}]}await save()}catch{db=null;state.reminderSilenced??={};state.someday??=[];state.affirmationSets??=[];state.savedPlans??=[];state.journal??=[];state.archivedBoards??=[];state.visionBoardMeta??={id:'current-board',name:'My vision board',visibility:'private'};state.visionBoardMeta.background??='paper';state.archivedAffirmations??=[];state.archivedDreams??=[];state.quotes??=[];state.savedItems??=[];state.settings??={darkMode:false};state.settings.themeChosen??=false;state.community??={name:'Your name',bio:'Building my next chapter.'};state.community.name??='Your name';state.community.bio??='Building my next chapter.';state.community.profilePhoto??='';updateStatus('Beta · this session only')}render();if(!state.settings.themeChosen)themeChoice()}
function photo(image,extra=''){return `<div class="photo photo-${esc(image)} ${extra}" role="img" aria-label="${esc(photoNames[image]||'Goal inspiration')}"></div>`}
function planProgress(p){return Math.round(p.milestones.filter(m=>m.done).length/p.milestones.length*100)||0}
function activeHabits(){return state.plans.filter(p=>(!p.start||p.start<=dayKey())&&!p.milestones.every(m=>m.done)).flatMap(p=>p.habits.map(h=>({...h,plan:p.name}))).concat(state.lifestyle.filter(r=>dueLifestyle(r)).flatMap(r=>(r.habits||[r]).map(h=>({...h,plan:'Ritual · '+r.name}))))}
function habitRow(h){const done=complete(h.id),off=done&&h.reminder,linked=state.affirmationSets?.some(set=>(set.habitIds||[]).includes(h.id));return `<div class="habit ${done?'complete':''}"><button class="check" ${action('complete',h.id)} aria-label="Complete ${esc(h[state.mode])}" aria-pressed="${done}">${done?'✓':''}</button><button class="habit-copy" ${action('habit-focus',h.id)}><div class="habit-name">${esc(h[state.mode])}</div><small>${esc(h.plan||h.name)}${linked?' · ✦ affirmation':''}</small></button><button class="habit-history" ${action('habit-history',h.id)} aria-label="View calendar progress for ${esc(h.full)}">▦</button><button class="time ${off?'reminder-off':''}" ${action('reminder',h.id)} aria-label="Reminder for ${esc(h.full)}">${off?'✓ off today':h.reminder?'◉ '+timeLabel(h.reminder):timeLabel(h.reminder)}</button></div>`}
function habitMeaning(id){const p=state.plans.find(plan=>plan.habits.some(h=>h.id===id));if(p)return {whys:p.whys?.length?p.whys:[p.why].filter(Boolean),values:(p.values||'').split(',').map(v=>v.trim()).filter(Boolean),label:p.name};const ritual=state.lifestyle.find(r=>(r.habits||[r]).some(h=>h.id===id));return ritual?{whys:[`This habit supports your ${ritual.name} ritual.`],values:(ritual.values||ritual.category||'').split(',').map(v=>v.trim()).filter(Boolean),label:ritual.name}:{whys:[],values:[],label:''}}
function habitHistory(id){const h=findHabit(id),meaning=habitMeaning(id);if(!h)return;const days=Array.from({length:35},(_,i)=>{const d=new Date();d.setDate(d.getDate()-34+i);const key=d.toISOString().slice(0,10),mode=completionMode(key,id);return {key,day:d.getDate(),done:Boolean(mode),mode,today:key===dayKey()}});const total=days.filter(d=>d.done).length;showDialog(`<span class="eyebrow">YOUR RHYTHM</span><h2>${esc(h.full)}</h2><section class="remember-whys"><span class="eyebrow">REMEMBER YOUR WHYS</span>${meaning.whys.map(why=>`<p>${esc(why)}</p>`).join('')||'<p>This habit is part of the life you are building.</p>'}<div class="tag-row">${meaning.values.map(v=>`<span class="tag">${esc(v)}</span>`).join('')}</div></section><p>${total} completed days in the last five weeks.</p><div class="completion-legend" aria-label="Completion colors"><span><i class="mode-full"></i>Locked in</span><span><i class="mode-light"></i>Lowkey</span></div><div class="habit-calendar">${['S','M','T','W','T','F','S'].map(day=>`<b>${day}</b>`).join('')}${days.map(day=>`<span class="${day.done?'done mode-'+day.mode:''} ${day.today?'today':''}" title="${day.key}${day.done?' · '+(day.mode==='light'?'Lowkey':'Locked in'):''}">${day.day}</span>`).join('')}</div><p class="helper">Your calendar remembers how you showed up each day.</p>`,false,'YOUR RHYTHM')}
function habitFocus(id){const h=findHabit(id),set=state.affirmationSets?.find(item=>(item.habitIds||[]).includes(id)),meaning=habitMeaning(id);if(!h)return;if(!set){habitHistory(id);return}showDialog(`<span class="eyebrow">AFFIRMATION + HABIT</span><h2>${esc(set.name)}</h2><section class="remember-whys"><span class="eyebrow">REMEMBER YOUR WHYS</span>${meaning.whys.map(why=>`<p>${esc(why)}</p>`).join('')}<div class="tag-row">${meaning.values.map(v=>`<span class="tag">${esc(v)}</span>`).join('')}</div></section><div class="affirmation-reading">${set.affirmations.map((line,i)=>`<p><span>${String(i+1).padStart(2,'0')}</span>${esc(line)}</p>`).join('')}</div>${set.audioSrc?`<button class="button soundscape-play" ${action('play-affirmation',set.id)}>▶ Play voice + ${esc(set.soundscape||'quiet')}</button>`:''}<button class="button" ${action('complete',id)}>${complete(id)?'✓ Completed today':'Complete this habit'}</button><button class="button secondary" ${action('habit-history',id)}>View progress calendar</button>`,true,'YOUR RHYTHM')}
function today(){const habits=activeHabits(),done=habits.filter(h=>complete(h.id)).length,pct=habits.length?Math.round(done/habits.length*100):0;const next=state.plans.flatMap(p=>p.milestones.filter(m=>!m.done).map(m=>({...m,plan:p.name,planId:p.id}))).sort((a,b)=>a.date&&b.date?a.date.localeCompare(b.date):a.date?-1:b.date?1:0).slice(0,3);return heading('SHOW UP FOR WHAT YOU WANT','Stay in motion.','Your gameplans and your lifestyle, in one daily lineup.')+`<div class="workspace"><section class="panel"><div class="motion-banner"><div><span class="eyebrow">BIG GOALS. REAL FOLLOW-THROUGH.</span><h2>You’ve got plans.<br>Make your move.</h2></div><div class="sticker sticker-star" aria-hidden="true"></div></div><div class="panel-inner"><div class="mode-row"><div><h3>Today’s lineup</h3><p>${state.mode==='light'?'Keep it moving with less effort.':'You’re locked in. Make your move.'}</p></div><div class="segmented" aria-label="Daily routine size">${['full','light'].map(m=>`<button ${action('mode',m)} aria-pressed="${state.mode===m}" class="${state.mode===m?'selected':''}">${m==='full'?'Locked in':'Lowkey'}</button>`).join('')}</div></div><div class="progress-caption"><strong>${done} of ${habits.length} complete</strong><span>${pct}%</span></div><div class="track" role="progressbar" aria-label="Today’s progress" aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100"><div style="width:${pct}%"></div></div><div class="habits">${habits.map(habitRow).join('')||'<p class="empty">Nothing scheduled today. Make a gameplan or add a Lifestyle ritual.</p>'}</div><div class="inline-actions"><button class="text-link" ${action('new-plan')}>＋ Gameplan</button><button class="text-link" ${action('new-lifestyle')}>＋ Lifestyle ritual</button></div></div></section><div class="aside-stack"><section class="panel panel-inner"><span class="eyebrow">MOVES TO MAKE</span><h2>Your next milestones</h2><div class="mini-timeline">${next.map(m=>`<button class="next-milestone" ${action('open-plan',m.planId)}><span class="milestone-dot"></span><span><small>${dateLabel(m.date)}</small><strong>${esc(m.title)}</strong><small>${esc(m.plan)}</small></span></button>`).join('')||'<p>Your milestones are complete. Set your next goal.</p>'}</div><a class="text-link" href="#goals">See your gameplans ↗</a></section><section class="panel mini-board"><div class="mini-board-images">${state.board.slice(0,2).map((v,i)=>tileHTML(v,i,true)).join('')}</div><div class="panel-inner"><h2>Keep your vision close.</h2><p class="helper">The reason behind the routine.</p><a href="#vision" class="text-link">Open your vision board ↗</a></div></section></div></div>`}
function gameplans(){const plans=planTab==='discover'?explore():`<div class="goals-grid">${state.plans.map(planCard).join('')||'<p class="empty">Your next goal starts with a gameplan.</p>'}</div>`;return heading('LIFE IS WHAT YOU MAKE IT','Plan for success','Dream it. Plan it. Make it yours.','<div class="inline-actions"><button class="button" '+action('new-plan')+'>＋ Gameplan</button><button class="button secondary" '+action('new-lifestyle')+'>＋ Ritual</button></div>')+`<h2 class="section-title gameplan-title">Glowup gameplans</h2><div class="view-tabs"><button ${action('plan-tab','mine')} aria-pressed="${planTab==='mine'}">My gameplans <span>${state.plans.length}</span></button><button ${action('plan-tab','discover')} aria-pressed="${planTab==='discover'}">Explore <span>Preview</span></button></div>${plans}<section class="goals-section"><div class="section-head"><div><span class="eyebrow">LIVING IN MY VALUES</span><h2>Lifestyle rituals</h2></div><button class="text-link" ${action('new-lifestyle')}>＋ Add ritual</button></div><div class="goals-grid ritual-grid">${state.lifestyle.map(r=>`<article class="panel panel-inner lifestyle-card"><div class="card-meta"><span>${esc(r.frequency)}</span><span>${(r.habits||[r]).length} ${(r.habits||[r]).length===1?'habit':'habits'}</span></div><h2>${esc(r.name)}</h2><p>${(r.habits||[r]).map(h=>esc(h.full)).join(' · ')}</p><button class="text-link" ${action('edit-lifestyle',r.id)}>Edit ritual ↗</button></article>`).join('')}</div></section>`}
function goalsOverview(){const all=state.plans.flatMap(plan=>plan.milestones.map((milestone,index)=>({...milestone,planId:plan.id,plan:plan.name,finish:index===plan.milestones.length-1})));const dated=all.filter(move=>move.date).sort((a,b)=>a.date.localeCompare(b.date)),flexible=all.filter(move=>!move.date).sort((a,b)=>(a.flexOrder??999)-(b.flexOrder??999));const moveCard=(move,i,flex=false)=>`<article class="timeframe-item ${move.done?'done':''} ${move.finish?'finish':''} ${flex?'flexible':''}"><div class="timeframe-marker"><span class="timeline-art art-${i%6}" aria-hidden="true"></span></div><div class="timeframe-card panel"><button class="timeframe-main" ${action('open-plan',move.planId)}><div class="card-meta"><span class="eyebrow">${esc(move.plan)}</span><strong>${dateLabel(move.date)}</strong></div><h2>${esc(move.title)}</h2>${move.finish?'<span class="finish-label">Finish ✦</span>':''}</button>${flex?`<div class="flex-move-controls" aria-label="Move ${esc(move.title)}"><button ${action('move-flex-milestone',move.planId+'|'+move.id+'|-1')} ${i===0?'disabled':''} aria-label="Move earlier">↑</button><button ${action('move-flex-milestone',move.planId+'|'+move.id+'|1')} ${i===flexible.length-1?'disabled':''} aria-label="Move later">↓</button></div>`:''}</div></article>`;return heading('BUILD YOURSELF FIRST','Goal','Lock in. Build what you keep dreaming about.')+`<section class="goals-section"><div class="section-head"><div><span class="eyebrow">MAKE IT HAPPEN</span><h2>Glowup gameplan to the finish line</h2></div><a class="text-link" href="#goals">Edit plans ↗</a></div><div class="goal-timeframe glow-road">${dated.map((move,i)=>moveCard(move,i)).join('')||(!flexible.length?'<p class="empty">Add milestones to a gameplan to build your path.</p>':'')}</div>${flexible.length?`<div class="flexible-goals-head"><span class="eyebrow">WHEN I GET THERE</span><p>No deadline. Move these milestones into the order that feels right.</p></div><div class="goal-timeframe glow-road flexible-road">${flexible.map((move,i)=>moveCard(move,i,true)).join('')}</div>`:''}</section><section class="goals-section lifestyle-values-section"><div class="section-head"><div><span class="eyebrow">EVERYDAY ALIGNMENT</span><h2>Living in my values</h2></div><a class="text-link" href="#goals">Edit rituals ↗</a></div><div class="lifestyle-summary-grid">${state.lifestyle.map(ritual=>`<button class="panel lifestyle-summary" ${action('edit-lifestyle',ritual.id)}><div class="card-meta"><span>${esc(ritual.frequency)}</span><span>${(ritual.habits||[ritual]).length} ${(ritual.habits||[ritual]).length===1?'habit':'habits'}</span></div><h3>${esc(ritual.name)}</h3><p>${(ritual.habits||[ritual]).map(h=>esc(h.full)).join(' · ')}</p></button>`).join('')}</div></section><section class="goals-section someday-section"><div class="section-head"><div><span class="eyebrow">WHEN THE SPACE OPENS UP</span><h2>Someday</h2></div><button class="text-link" ${action('new-someday')}>＋ Add someday goal</button></div><div class="someday-grid">${state.someday.map(goal=>`<article class="panel someday-card"><div><h3>${esc(goal.name)}</h3>${goal.why?`<p>${esc(goal.why)}</p>`:''}${goal.inspiration?`<p><strong>Inspired by:</strong> ${esc(goal.inspiration)}</p>`:''}</div><button class="icon-btn" ${action('remove-someday',goal.id)}>×</button></article>`).join('')||'<div class="empty">No pressure and no deadline. Save an idea here when it belongs in your future.</div>'}</div></section>`}function planCard(p){const pct=planProgress(p);return `<article class="panel goal-card"><div class="plan-cover">${upgrade.cover(p)}<span class="cover-tag">${esc(p.category)}</span></div><div class="panel-inner"><div class="card-meta"><span>${esc(p.horizon)}</span><span>${p.visibility==='public'?'Public · preview':'Private'}</span></div><h2>${esc(p.name)}</h2><p>${esc((p.whys?.[0])||p.why||'Add your why and make this plan your own.')}</p><div class="progress-caption"><span>${p.milestones.filter(m=>m.done).length}/${p.milestones.length} milestones</span><strong>${pct}%</strong></div><div class="track"><div style="width:${pct}%"></div></div><div class="goal-bottom"><span>${p.milestones.some(m=>m.date)||p.start?'Through '+dateLabel([...p.milestones].reverse().find(m=>m.date)?.date||p.start):'When I get there'}</span><button class="text-link" ${action('open-plan',p.id)}>Open plan ↗</button></div></div></article>`}
function explore(){const own=state.plans.filter(p=>p.visibility==='public').map(p=>({...publicPlan(p),author:'Your public preview'}));return `<div class="notice"><strong>Sharing preview</strong><p>Try the discovery and copying experience here. These sample plans and your public previews stay on this device; they aren’t visible to other people yet.</p></div><div class="goals-grid">${[...own,...templates].map(p=>`<article class="panel goal-card"><div class="plan-cover">${upgrade.cover(p)}<span class="cover-tag">${esc(p.category)}</span></div><div class="panel-inner"><div class="card-meta"><span>${esc(p.author)}</span><span>${p.duration} days</span></div><h2>${esc(p.name)}</h2><p>${esc(p.intro)}</p><button class="button secondary" ${action('public-view',p.id)}>View gameplan ↗</button><button class="text-link" ${action('save-plan',p.id)}>♡ Save for someday</button></div></article>`).join('')}</div>`}
function lifestyle(){return heading('YOUR EVERYDAY STANDARD','Lifestyle rituals','The routines you keep, made from habits that work together.','<button class="button" '+action('new-lifestyle')+'>＋ Add ritual</button>')+`<div class="lifestyle-lead"><div><span class="eyebrow">BUILT INTO YOUR LIFE</span><h2>Build rituals that feel<br>like your life.</h2><p>Group the habits you want to keep. Gameplan milestones can stay focused on a finish line.</p></div><div class="sticker sticker-orbit" aria-hidden="true"></div></div><div class="goals-grid ritual-grid">${state.lifestyle.map(r=>`<article class="panel panel-inner lifestyle-card"><div class="card-meta"><span class="tag">${esc(r.category)}</span><span>${esc(r.frequency)}</span></div><h2>${esc(r.name)}</h2><div class="ritual-habits">${(r.habits||[r]).map((h,i)=>`<div class="ritual-habit"><span class="ritual-number">${i+1}</span><div><strong>${esc(h.full)}</strong><small><b>Lowkey:</b> ${esc(h.light)}</small></div><button class="text-link" ${action('reminder',h.id)}>${timeLabel(h.reminder)}</button></div>`).join('')}</div><div class="goal-bottom"><span>${(r.habits||[r]).length} ${(r.habits||[r]).length===1?'habit':'habits'}</span><button class="text-link" ${action('edit-lifestyle',r.id)}>Edit ritual ↗</button></div></article>`).join('')||'<p class="empty">Add a ritual made from the habits you want to keep.</p>'}</div>`}
function vision(){const tabs=`<nav class="vision-tabs" aria-label="Vision space">${[['board','Vision Board'],['affirmations','Affirmations'],['dreams','Dreams'],['archive','Archive']].map(([id,label])=>`<button ${action('vision-tab',id)} aria-pressed="${visionTab===id}">${label}</button>`).join('')}</nav>`;if(visionTab==='affirmations')return tabs+heading('WORDS TO RETURN TO','Call in that energy.','Affirmation sets for the life you’re calling in.','<button class="button" '+action('new-affirmation')+'>＋ New set</button>')+`<div class="affirmation-grid">${state.affirmationSets.map(set=>`<button class="affirmation-card ${set.visibility==='public'?'is-public':''}" ${action('open-affirmation',set.id)}><span class="affirmation-spark">✦</span><small>${set.visibility==='public'?'Public set':'Just for me'}</small><h2>${esc(set.name)}</h2><p>${esc(set.affirmations[0]||'Add an affirmation')}</p><span>${set.audioSrc?'🎙 Voice set · ':''}${set.affirmations.length} affirmations →</span></button>`).join('')}</div>`;if(visionTab==='dreams')return tabs+heading('KEEP THE POSSIBILITY CLOSE','Dreams','A soft place for what you may make room for someday.','<button class="button" '+action('new-someday')+'>＋ Add a dream</button>')+`<div class="dream-grid">${state.someday.map((dream,i)=>`<article class="dream-note dream-${i%3}"><span class="dream-tape"></span><h2>${esc(dream.name)}</h2>${dream.why?`<p>${esc(dream.why)}</p>`:''}${dream.inspiration?`<p class="dream-inspiration"><strong>Inspired by</strong><br>${esc(dream.inspiration)}</p>`:''}<div class="inline-actions"><button class="text-link" ${action('archive-dream',dream.id)}>Archive</button><button class="icon-btn" ${action('remove-someday',dream.id)}>×</button></div></article>`).join('')||'<div class="empty">Save a dream here when it matters.</div>'}</div>`;if(visionTab==='archive')return tabs+heading('EVERYTHING YOU STILL WANT TO KEEP','Vision archive','Past boards, affirmation sets, and dreams stay close without crowding what is current.')+`<section class="archive-section"><h2>Vision boards</h2><div class="archived-board-grid">${state.archivedBoards.map(board=>`<article class="panel archived-board-card"><div class="archived-preview">${board.items.slice(0,4).map((item,i)=>tileHTML(item,i,true)).join('')}</div><div class="panel-inner"><div class="card-meta"><span>${board.visibility==='public'?'Public':'Private'}</span><span>${board.items.length} pieces</span></div><h2>${esc(board.name)}</h2><div class="inline-actions"><button class="button secondary" ${action('restore-board',board.id)}>Restore</button><button class="text-link danger" ${action('delete-archived-board',board.id)}>Delete</button></div></div></article>`).join('')||'<p class="empty">No archived boards.</p>'}</div></section><section class="archive-section"><h2>Affirmation sets</h2><div class="affirmation-grid">${state.archivedAffirmations.map(set=>`<article class="affirmation-card"><h2>${esc(set.name)}</h2><p>${esc(set.affirmations?.[0]||'')}</p><div class="inline-actions"><button class="text-link" ${action('restore-affirmation',set.id)}>Restore</button><button class="text-link danger" ${action('delete-archived-affirmation',set.id)}>Delete</button></div></article>`).join('')||'<p class="empty">No archived affirmation sets.</p>'}</div></section><section class="archive-section"><h2>Dreams</h2><div class="dream-grid">${state.archivedDreams.map(d=>`<article class="dream-note"><h2>${esc(d.name)}</h2><p>${esc(d.why||'')}</p><div class="inline-actions"><button class="text-link" ${action('restore-dream',d.id)}>Restore</button><button class="text-link danger" ${action('delete-archived-dream',d.id)}>Delete</button></div></article>`).join('')||'<p class="empty">No archived dreams.</p>'}</div></section>`;const edit=visionMode==='edit',bg=state.visionBoardMeta.background||'paper';return tabs+heading('YOUR FUTURE, IN FULL COLOR',esc(state.visionBoardMeta.name),'See it, believe it, achieve it.',`<div class="vision-heading-actions"><button class="button secondary" ${action('board-mode',edit?'view':'edit')}>${edit?'Done editing':'Edit board'}</button>${edit?`<button class="button" ${action('new-tile')}>＋ Add</button>`:''}</div>`)+`<div class="board-commandbar"><span class="tag">${state.visionBoardMeta.visibility==='public'?'Public board':'Private · on this device'}</span><button class="text-link" ${action('save-board')}>Name & save</button><button class="text-link" ${action('board-style')}>Background</button><button class="text-link" ${action('download-board')}>Save to device ↓</button><button class="text-link" ${action('share-board')}>${state.visionBoardMeta.visibility==='public'?'Sharing on':'Post board'}</button><button class="text-link" ${action('archive-board')}>Archive</button><button class="text-link" ${action('new-board')}>New board</button></div>${edit?'<div class="board-toolbar"><span>Drag any piece. Tap a piece to edit its size, style, tilt, or connection.</span><span class="tag">Layered editor</span></div>':'<p class="helper still-board-note">Finished view · open Edit board to move, resize, or decorate.</p>'}<div id="vision-canvas" class="collage scrapbook-collage collage-bg-${esc(bg)} ${edit?'board-editing':'board-still'}">${state.board.map((v,i)=>tileHTML(v,i,!edit)).join('')||'<div class="empty">Start with an image, quote, affirmation, or graphic.</div>'}</div>`}
function boardForm(){const meta=state.visionBoardMeta;showDialog(`<h2>Name and save this vision.</h2><form id="board-form"><label>Board name<input name="name" required maxlength="70" value="${esc(meta.name)}"></label><label>Visibility<select name="visibility"><option value="private">Private</option><option value="public" ${meta.visibility==='public'?'selected':''}>Public · show on my profile and Explore</option></select></label><button class="button">Save board</button></form>`,false,'YOUR BOARD');$('#board-form').onsubmit=async e=>{e.preventDefault();const f=e.target,name=f.elements.name.value.trim();if(!name)return error(f,'Name your vision board.');meta.name=name;meta.visibility=f.elements.visibility.value;dialog.close();render();await save('Vision board saved.')}}function boardStyleForm(){const meta=state.visionBoardMeta;showDialog(`<h2>Set the mood behind your collage.</h2><form id="board-style-form"><div class="background-choices">${[['paper','Soft paper'],['blush','Blush'],['lime','Lime'],['aqua','Aqua'],['lavender','Lavender'],['paisley','Paisley'],['grid','Notebook grid'],['stars','Night stars']].map(([v,l])=>`<label class="background-choice"><input type="radio" name="background" value="${v}" ${meta.background===v?'checked':''}><span class="collage-bg-${v}"></span>${l}</label>`).join('')}</div><button class="button">Use this background</button></form>`,false,'BOARD BACKGROUND');$('#board-style-form').onsubmit=async e=>{e.preventDefault();meta.background=new FormData(e.target).get('background')||'paper';dialog.close();render();await save('Board background updated.')}}
function archiveCurrentBoard(){state.archivedBoards.unshift({id:uid(),name:state.visionBoardMeta.name,visibility:state.visionBoardMeta.visibility,background:state.visionBoardMeta.background,items:structuredClone(state.board),archived:dayKey()});state.board=[];state.visionBoardMeta={id:uid(),name:'My next vision board',visibility:'private',background:'paper'};visionMode='edit';render();save('Vision board moved to Archive.')}
function tileHTML(v,i,preview=false){const positions=[[2,3],[48,7],[28,29],[4,47],[55,49],[19,68],[62,73],[38,83]],pos=positions[i%positions.length],x=Number.isFinite(Number(v.x))?Number(v.x):pos[0],y=Number.isFinite(Number(v.y))?Number(v.y):pos[1],baseZ=Number(v.z)||i+1,z=(v.kind==='text'||v.kind==='affirmation'?100:v.kind==='graphic'?60:0)+baseZ,safeImage=v.image==='own'&&/^data:image\/(png|jpeg|webp);base64,/.test(v.src||''),open=preview?'':` ${action('vision-context',v.id)} role="button" tabindex="0"`,affirm=state.affirmationSets.find(a=>a.id===v.affirmationId),text=v.kind==='affirmation'?(affirm?.affirmations?.[0]||'Choose an affirmation'):v.text;return `<article class="board-tile tile-${esc(v.size||'normal')} color-${esc(v.color||'white')} type-${esc(v.kind)} quote-${esc(v.quoteStyle||'floating')} font-${esc(v.font||'display')}" data-board-id="${esc(v.id)}" style="--x:${x};--y:${y};--z:${z};--tilt:${Number(v.rotation)||0}deg">${v.kind==='photo'?`<div class="tile-media"${open}>${safeImage?`<img src="${v.src}" alt="${esc(text||'Vision photo')}">`:photo(v.image)}</div>`:''}${v.kind==='graphic'||v.sticker!=='none'?`<div class="sticker sticker-${esc(v.kind==='graphic'?v.sticker:v.sticker)}" aria-hidden="true"></div>`:''}${text?`<div class="tile-caption"${open}>${esc(text)}</div>`:''}${preview?'':`<button class="tile-edit" ${action('edit-tile',v.id)} aria-label="Edit board item ${i+1}">✎</button><button class="drag-handle" aria-label="Drag board item ${i+1}"><span></span></button>`}</article>`}
function visionContext(id){const v=state.board.find(item=>item.id===id);if(!v)return;let title=v.text||photoNames[v.image]||'Your vision',body='';if(v.linkType==='plan'){const p=state.plans.find(x=>x.id===v.linkId);if(p){title=p.name;body=`<span class="eyebrow">CONNECTED GAMEPLAN</span><p>${esc(p.why)}</p><div class="tag-row">${p.values.split(',').map(x=>`<span class="tag">${esc(x.trim())}</span>`).join('')}</div>${timeline(p,false)}`}}else if(v.linkType==='ritual'){const r=state.lifestyle.find(x=>x.id===v.linkId);if(r){title=r.name;body=`<span class="eyebrow">CONNECTED LIFESTYLE</span><p>${(r.habits||[r]).map(h=>esc(h.full)).join(' · ')}</p>`}}else if(v.linkType==='value'){title=v.linkId;body='<span class="eyebrow">CONNECTED VALUE</span><p>Keep this value visible while you shape the life around it.</p>'}else if(v.kind==='affirmation'){const set=state.affirmationSets.find(a=>a.id===v.affirmationId);if(set){title=set.name;body=`<div class="affirmation-reading">${set.affirmations.map((x,i)=>`<p><span>${String(i+1).padStart(2,'0')}</span>${esc(x)}</p>`).join('')}</div>`}}showDialog(`<h2>${esc(title)}</h2>${body||'<p>This piece can connect to a gameplan, lifestyle ritual, value, or affirmation.</p>'}<button class="button secondary" ${action('edit-tile',v.id)}>Edit connection</button>`,true,'VISION CONNECTION')}
function reflectionAnswers(r){const prompts=[['why','Why I want this'],['values','Values connected to it'],['vision','What I picture changing'],['growth','Where I have room to grow'],['next','What I’ll do differently']];return prompts.filter(([key])=>r[key]).map(([key,label])=>`<p><strong>${label}</strong><br>${esc(r[key])}</p>`).join('')}
function reflect(){if(!state.plans.some(p=>p.id===selectedGrowth))selectedGrowth=state.plans[0]?.id||'';const p=state.plans.find(p=>p.id===selectedGrowth);if(!p)return heading('GET CLEAR ON WHAT MATTERS','Room to Grow','Progress is also learning what works for you.')+'<div class="empty">Create a gameplan first, then explore the why behind it.<p><button class="button" '+action('new-plan')+'>Create a gameplan</button></p></div>';const entries=state.reflections.filter(r=>r.planId===p.id);return heading('GET CLEAR ON WHAT MATTERS','Room to Grow','Reflect on your why, your values, and where you have room to grow.')+`<div class="growth-selectors"><div><label for="growth-plan">Your gameplan</label><select id="growth-plan">${state.plans.map(g=>option(g.id,p.id,g.name)).join('')}</select></div><div><label for="growth-horizon">Look ahead</label><select id="growth-horizon">${horizons.map(h=>option(h,growthHorizon)).join('')}</select></div></div><div class="reflection-layout"><section class="panel"><div class="growth-banner"><span class="eyebrow">${esc(growthHorizon.toUpperCase())} FROM NOW</span><h2>What are you growing toward?</h2></div><form id="growth-form" class="panel-inner"><p class="reflection-instruction"><strong>Start wherever you need.</strong><br>Answer one question or all five. You can come back to the rest later.</p><label for="growth-why">Why do you want to achieve this?</label><textarea id="growth-why" name="why" maxlength="2000" placeholder="What makes this goal yours?"></textarea><label for="growth-values">What values does it connect to?</label><input id="growth-values" name="values" maxlength="250" placeholder="e.g. Freedom, confidence, curiosity"><label for="growth-vision">What do you picture changing in your life?</label><textarea id="growth-vision" name="vision" maxlength="2000" placeholder="Describe the life this goal supports."></textarea><label for="growth-room">Where do you have room to grow?</label><textarea id="growth-room" name="growth" maxlength="2000" placeholder="Skills, habits, beliefs, or support you want to build."></textarea><label for="growth-next">What will you do differently?</label><input id="growth-next" name="next" maxlength="300" placeholder="Your next move"><p class="helper">Private reflection. Never included in a public gameplan preview.</p><p class="form-error" role="alert" tabindex="-1"></p><button class="button" type="submit">Save what I answered ↗</button></form></section><aside class="panel panel-inner"><span class="eyebrow">YOUR PERSPECTIVE, OVER TIME</span><h2>Growth notes</h2>${entries.length?entries.map(r=>`<article class="entry"><small>${dateLabel(r.date)} · ${esc(r.horizon)}</small><h3>${esc(p.name)}</h3>${reflectionAnswers(r)}</article>`).join(''):'<div class="empty">Your goals can evolve.<br>Keep a record of what matters and what changes.</div>'}</aside></div>`}
function diary(){const entries=[...(state.journal||[]).map(entry=>({...entry,type:'freewrite'})),...(state.quotes||[]).map(entry=>({...entry,type:'quote',title:`“${entry.quote}”`,text:`— ${entry.author||'Unknown'}`})),...(state.reflections||[]).map(entry=>({...entry,type:'reflection',title:state.plans.find(p=>p.id===entry.planId)?.name||'Reflection',text:entry.why||entry.vision||entry.growth||entry.next||''})),...((state.community?.updates)||[]).map(entry=>({...entry,type:'journey'}))].sort((a,b)=>(b.date||'').localeCompare(a.date||''));const visible=diaryFilter==='all'?entries:entries.filter(x=>x.type===diaryFilter);const filters=[['all','All entries'],['freewrite','Freewrite'],['journey','Journey reflections'],['reflection','Guided reflections'],['quote','Favorite quotes']];return heading('YOUR STORY, AS IT HAPPENS','Diary','Freewrites, journey reflections, quotes, and guided reflections in one private timeline.','<button class="button" '+action('journal-now')+'>＋ Journal now</button>')+`<div class="diary-filters">${filters.map(([id,label])=>`<button ${action('diary-filter',id)} aria-pressed="${diaryFilter===id}">${label}</button>`).join('')}</div><div class="diary-timeline">${visible.map(item=>`<article class="panel diary-entry type-${item.type}"><div class="card-meta"><span class="tag">${esc(filters.find(f=>f[0]===item.type)?.[1]||item.type)}</span><span>${item.date?dateLabel(item.date):'Today'}</span></div><h2>${esc(item.title||item.planName||'A note to myself')}</h2><p>${esc(item.text||'')}</p>${item.photo?`<img class="journey-photo" src="${esc(item.photo)}" alt="">`:''}</article>`).join('')||'<div class="empty">Nothing in this view yet.</div>'}</div>`}
function journalMenu(){showDialog(`<h2>What do you want to capture?</h2><div class="journal-options"><button class="journal-option" ${action('free-journal')}><strong>Freewrite</strong><span>Write without a prompt or finish line.</span></button><button class="journal-option" ${action('journey-reflection')}><strong>Journey reflection</strong><span>Capture what changed, what worked, and what comes next.</span></button><button class="journal-option" ${action('new-quote')}><strong>Favorite quote</strong><span>Save the words and who said them.</span></button><button class="journal-option" ${action('guided-reflection')}><strong>Guided reflection</strong><span>Think through your why, values, and growth.</span></button></div>`,false,'JOURNAL NOW')}function freeJournalForm(){showDialog(`<h2>Freewrite.</h2><form id="journal-form"><label>Title<input name="title" maxlength="100" placeholder="A note to myself"></label><label>Your entry<textarea name="text" required rows="12" maxlength="5000" placeholder="Write whatever needs somewhere to land."></textarea></label><p class="form-error" role="alert"></p><button class="button">Save to Diary</button></form>`,false,'FREEWRITE');$('#journal-form').onsubmit=async e=>{e.preventDefault();const f=e.target,text=f.elements.text.value.trim();if(!text)return error(f,'Write something before saving.');state.journal.unshift({id:uid(),title:f.elements.title.value.trim()||'A note to myself',text,date:dayKey()});dialog.close();location.hash='diary';render();await save('Freewrite saved to Diary.')}}function quoteForm(){const people=[['@alexinmotion','Alex Rivera'],['@julesgetsgoing','Jules Park'],['@samtakesoff','Sam Taylor']];showDialog(`<h2>Save words worth returning to.</h2><form id="quote-form"><label>Quote<textarea name="quote" required rows="5" maxlength="1000" placeholder="The words you want to keep"></textarea></label><label>Who is it by?<input name="author" maxlength="100" list="quote-people" placeholder="Author, source, or @person"><datalist id="quote-people">${people.map(([handle,name])=>`<option value="${handle}">${name}</option>`).join('')}</datalist></label><div class="mention-picker"><span>Tag someone</span><div>${people.map(([handle,name])=>`<button type="button" class="mention-chip" data-quote-mention="${handle}" title="${name}">${handle}</button>`).join('')}</div></div><p class="helper">Choose a person or type any @handle.</p><p class="form-error" role="alert"></p><button class="button">Save quote</button></form>`,false,'WORDS TO KEEP');const f=$('#quote-form');f.querySelectorAll('[data-quote-mention]').forEach(button=>button.onclick=()=>{f.elements.author.value=button.dataset.quoteMention;f.elements.author.focus()});f.onsubmit=async e=>{e.preventDefault();const quote=f.elements.quote.value.trim();if(!quote)return error(f,'Add the quote first.');state.quotes.unshift({id:uid(),quote,author:f.elements.author.value.trim(),date:dayKey()});dialog.close();diaryFilter='quote';render();await save('Quote saved.')}}
function savedHub(){const planItems=state.savedPlans.map(id=>templates.find(p=>p.id===id)).filter(Boolean).map(p=>({type:'plan',name:p.name,category:p.category,values:p.publicValues||[],detail:p.intro,id:p.id}));const boardItems=[...(state.board?.length?[{type:'board',name:state.visionBoardMeta?.name||'My vision board',detail:`${state.board.length} saved piece${state.board.length===1?'':'s'}`,category:'Vision board',values:[]}]:[]),...(state.archivedBoards||[]).map(board=>({type:'board',name:board.name||'Archived vision board',detail:`${board.items?.length||0} saved pieces`,category:'Vision board',values:[]}))];const imageItems=(state.savedItems||[]).filter(x=>x.type==='image');const quoteItems=(state.quotes||[]).map(q=>({type:'quote',name:q.quote,detail:q.author,category:'Words',values:[]}));const affirmationItems=(state.affirmationSets||[]).map(a=>({type:'affirmation',name:a.name,detail:a.affirmations[0],category:'Mindset',values:[]}));const items=[...planItems,...boardItems,...imageItems,...quoteItems,...affirmationItems];const types=[['all','Everything'],['plan','Gameplans'],['board','Vision Boards'],['image','Images'],['quote','Quotes'],['affirmation','Affirmations']];return heading('EVERYTHING WORTH KEEPING','Saved','Your plans, boards, images, words, and inspiration in one place.')+`<div class="saved-toolbar"><div class="diary-filters">${types.map(([id,label])=>`<button ${action('saved-filter',id)} aria-pressed="${savedType===id}">${label}</button>`).join('')}</div><label>Filter by category or value<input id="saved-search" type="search" placeholder="Try Fitness, Freedom, Curiosity…"></label></div><div id="saved-grid" class="saved-grid">${items.filter(x=>savedType==='all'||x.type===savedType).map(item=>`<article class="panel saved-card" data-search="${esc([item.name,item.detail,item.category,...item.values].join(' ').toLowerCase())}"><span class="eyebrow">${esc(item.type==='board'?'vision board':item.type)}</span><h2>${esc(item.name)}</h2><p>${esc(item.detail||'')}</p><div class="tag-row"><span class="tag">${esc(item.category||'Saved')}</span>${item.values.map(v=>`<span class="tag">${esc(v)}</span>`).join('')}</div></article>`).join('')||'<p class="empty">Save something you love and it will wait here.</p>'}</div>`}
function render(){upgrade.init();document.body.classList.toggle('dark-mode',Boolean(state.settings?.darkMode));const page=route();$('#navigation').innerHTML=Object.entries(labels).filter(([key])=>!['lifestyle','reflect'].includes(key)).map(([key,label])=>`<a href="#${key}" class="${page===key?'active':''}" ${page===key?'aria-current="page"':''}>${svg(key)}<span>${label}</span></a>`).join('');app.innerHTML=({today,overview:goalsOverview,goals:gameplans,lifestyle,vision,reflect,diary,saved:savedHub,explore:upgrade.explorePage,profile:upgrade.profilePage}[page])();$('#date').textContent=new Date().toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'});if(page==='reflect'){if(!horizons.includes(growthHorizon)){const select=$('#growth-horizon');select.add(new Option(growthHorizon,growthHorizon));select.value=growthHorizon}bindGrowth();}if(page==='saved')$('#saved-search').oninput=e=>document.querySelectorAll('.saved-card').forEach(card=>card.hidden=!card.dataset.search.includes(e.target.value.toLowerCase()));upgrade.decorate()}
function themeChoice(){showDialog(`<div class="theme-welcome"><h2>Choose your glow.</h2><p>Pick the look that feels best today.</p><form id="theme-choice-form"><fieldset class="theme-choice-cards"><legend>How do you want Glow Getters to look?</legend><label class="theme-choice light-choice"><input type="radio" name="appearance" value="light" checked><span><strong>Light mode</strong><small>Bright, airy, and easygoing.</small></span></label><label class="theme-choice dark-choice"><input type="radio" name="appearance" value="dark"><span><strong>Dark mode</strong><small>Calm, grounded, and lower glare.</small></span></label></fieldset><p class="helper theme-reminder">You can change this anytime in Profile → Settings.</p><button class="button">Use this look</button></form></div>`,false,'WELCOME TO GLOW GETTER');const close=$('.dialog-top .icon-btn',dialog);if(close)close.hidden=true;const f=$('#theme-choice-form');for(const input of f.querySelectorAll('[name="appearance"]'))input.onchange=()=>document.body.classList.toggle('dark-mode',input.value==='dark'&&input.checked);f.onsubmit=async e=>{e.preventDefault();state.settings.darkMode=f.elements.appearance.value==='dark';state.settings.themeChosen=true;dialog.close();render();await save('Your look is set. You can change it anytime in Settings.')}}
function timeline(p,interactive=true){return `<ol class="timeline">${p.milestones.map((m,i)=>`<li class="${m.done?'done':''}"><div class="timeline-marker">${interactive?`<button ${action('milestone',p.id+'|'+m.id)} aria-label="Complete milestone: ${esc(m.title)}" aria-pressed="${m.done}">${m.done?'✓':i+1}</button>`:`<span>${i+1}</span>`}</div><div><small>Level ${i+1} · ${m.date?dateLabel(m.date):m.day?'Day '+m.day:'When I get there'}</small><strong>${esc(m.title)}</strong>${!m.done&&m.date&&m.date<dayKey()?'<span class="overdue">Past target date · pivot if needed</span>':''}</div></li>`).join('')}</ol>`}
function openPlan(id){const p=state.plans.find(p=>p.id===id);if(!p)return;const whys=p.whys?.length?p.whys:[p.why].filter(Boolean);showDialog(`<div class="plan-detail-cover">${upgrade.cover(p)}</div><div class="card-meta"><span>${esc(p.category)} · ${esc(p.horizon)}</span><span>${p.visibility==='public'?'Public · preview':'Private'}</span></div><h2>${esc(p.name)}</h2><div class="inline-actions"><button class="button secondary" ${action('edit-plan',p.id)}>Edit gameplan</button><button class="text-link" ${action('share-plan',p.id)}>Sharing settings ↗</button></div><section class="plan-why"><span class="eyebrow">REMEMBER YOUR WHYS · PRIVATE</span>${whys.map((why,i)=>`<p><strong>${String(i+1).padStart(2,'0')}</strong> ${esc(why)}</p>`).join('')||'<p>Add what makes this goal matter to you.</p>'}<div class="tag-row">${p.values.split(',').filter(Boolean).map(v=>`<span class="tag">${esc(v.trim())}</span>`).join('')}</div>${p.vision?`<p class="helper">Your vision: ${esc(p.vision)}</p>`:''}<button class="text-link" ${action('grow-plan',p.id)}>Reflect + Journal ↗</button></section><div class="section-head"><h3>Your levels to the finish line</h3><span class="tag">${planProgress(p)}% complete</span></div>${timeline(p)}<h3>Habits by level</h3>${p.habits.map(h=>`<div class="detail-habit"><strong>${esc(h.full)}</strong><span>${esc(h.level||'Level 1')} · ${esc(p.milestones.find(m=>m.id===h.milestoneId)?.title||'Whole gameplan')}</span><span>Lowkey: ${esc(h.light)}</span><button class="text-link" ${action('reminder',h.id)}>${timeLabel(h.reminder)}</button></div>`).join('')}`,true,'YOUR GLOWUP GAMEPLAN')}
function milestoneRow(m,i){return `<div class="milestone-editor" data-row-id="${esc(m.id)}"><span class="row-index">${i+1}</span><div><label>Milestone<input name="milestone-title" aria-label="Milestone ${i+1} name" required maxlength="100" value="${esc(m.title)}" placeholder="What will you achieve?"></label></div><div><label>Target date <span class="optional-label">Optional</span><input type="date" name="milestone-date" aria-label="Milestone ${i+1} target date" value="${esc(m.date||'')}"><small>Leave blank for “When I get there.”</small></label></div><button type="button" class="icon-btn" ${action('remove-milestone',m.id)} aria-label="Remove milestone ${i+1}">×</button></div>`}
function habitEditor(h,i){return `<div class="habit-editor" data-row-id="${esc(h.id)}"><div class="field-pair"><label>Locked-in habit<input name="habit-full" required maxlength="100" value="${esc(h.full)}" placeholder="e.g. Walk for 20 minutes"></label><label>Lowkey version<input name="habit-light" required maxlength="100" value="${esc(h.light)}" placeholder="e.g. Walk for 5 minutes"></label></div><div class="field-pair"><label>Plan for milestone<select name="habit-milestone"><option value="">Whole gameplan</option>${currentDraft.milestones.map((m,n)=>option(m.id,h.milestoneId||'',`Level ${n+1}: ${m.title||'Untitled milestone'}`)).join('')}</select></label><label>Level / pivot<input name="habit-level" maxlength="20" value="${esc(h.level||'Level 1')}" placeholder="Level 1 or 1.1"></label></div><div class="habit-editor-bottom"><label>Reminder<input type="time" name="habit-reminder" value="${esc(h.reminder)}"></label><button type="button" class="text-link" ${action('remove-habit',h.id)}>Remove habit</button></div></div>`}
function planForm(id){const source=state.plans.find(p=>p.id===id);currentDraft=source?structuredClone(source):{id:uid(),name:'',why:'',whys:[],values:'',vision:'',intro:'',category:'Personal',image:'gym',start:'',horizon:'1 month',visibility:'private',milestones:[{id:uid(),title:'',date:'',done:false}],habits:[{id:uid(),full:'',light:'',reminder:'',level:'Level 1',milestoneId:''}]};const p=currentDraft;showDialog(`<h2>${source?'Edit your gameplan':'Make your next move'}</h2><form id="plan-form"><label>What are you working toward?<input name="name" required maxlength="70" value="${esc(p.name)}" placeholder="Name your goal"></label><div class="field-pair"><label>Category<select name="category">${categories.map(c=>option(c,p.category)).join('')}</select></label><label>Time horizon<select name="horizon">${horizons.map(h=>option(h,p.horizon)).join('')}</select></label></div><label>Start date <span class="optional-label">Optional</span><input type="date" name="start" value="${p.start||''}"><small>Leave blank for a goal that starts when you are ready.</small></label><label>Gameplan visibility<select id="plan-visibility" name="visibility">${option('private',p.visibility,'Private')}${option('public',p.visibility,'Public profile · preview')}</select><small>Public adds this gameplan to your profile preview on this device. Your private whys, values, vision, progress, and reminders stay hidden.</small></label><label id="plan-public-intro-wrap" hidden>Public introduction<textarea name="intro" maxlength="700" placeholder="What could this gameplan help someone work toward?">${esc(p.intro||'')}</textarea><small>This description appears in the public preview.</small></label><details class="why-editor" open><summary>Your whys, values & vision <span>Private</span></summary><label>Your whys <textarea name="why" required maxlength="2000" placeholder="One reason per line">${esc((p.whys?.length?p.whys:[p.why]).filter(Boolean).join('\n'))}</textarea></label><p class="helper">Add as many reasons as you need—one per line.</p><label>Values<input id="plan-values" name="values" required value="${esc(p.values)}"></label><label>Your vision<textarea name="vision" required>${esc(p.vision)}</textarea></label></details><h3 class="form-section">Plan your levels</h3><div id="milestone-rows">${p.milestones.map(milestoneRow).join('')}</div><button type="button" class="text-link" ${action('add-milestone')}>＋ Add level</button><h3 class="form-section">Choose habits for each level</h3><p class="helper">Plan habits ahead, and use decimals such as Level 1.1 when you pivot.</p><div id="habit-rows">${p.habits.map(habitEditor).join('')}</div><button type="button" class="text-link" ${action('add-habit')}>＋ Add habit or pivot</button><label>Cover image<select name="image">${Object.entries(photoNames).map(([k,l])=>option(k,p.image,l)).join('')}</select></label><p class="form-error" role="alert"></p><button class="button">Save gameplan ↗</button></form>`,true,'BUILD YOUR GAMEPLAN');const planFormEl=$('#plan-form'),visibility=planFormEl.elements.visibility,introWrap=$('#plan-public-intro-wrap'),toggleVisibility=()=>introWrap.hidden=visibility.value!=='public';visibility.addEventListener('change',toggleVisibility);toggleVisibility();planFormEl.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,data=new FormData(f),values=Object.fromEntries(['name','category','horizon','start','visibility','intro','why','values','vision','image'].map(k=>[k,String(data.get(k)||'').trim()]));if(['name','why','values','vision'].some(k=>!values[k]))return error(f,'Add your goal, whys, values, and vision before saving.');if(values.visibility==='public'&&!values.intro)return error(f,'Add a public introduction before making this gameplan public.');readDraftRows();let milestones;try{milestones=validMilestones(currentDraft.milestones,values.start)}catch(err){return error(f,err.message)}if(!currentDraft.habits.length||currentDraft.habits.some(h=>!h.full||!h.light))return error(f,'Add at least one complete habit.');Object.assign(currentDraft,values,{why:values.why.split(/\r?\n/).filter(Boolean)[0]||'',whys:values.why.split(/\r?\n/).map(x=>x.trim()).filter(Boolean),milestones});const idx=state.plans.findIndex(g=>g.id===p.id);if(idx>=0)state.plans[idx]=structuredClone(currentDraft);else state.plans.push(structuredClone(currentDraft));dialog.close();render();await save('Gameplan saved. Stay in motion.');openPlan(p.id)})}
function readDraftRows(){currentDraft.milestones=[...document.querySelectorAll('.milestone-editor')].map(row=>({id:row.dataset.rowId,title:$('[name="milestone-title"]',row).value.trim(),date:$('[name="milestone-date"]',row).value,done:currentDraft.milestones.find(m=>m.id===row.dataset.rowId)?.done||false,flexOrder:currentDraft.milestones.find(m=>m.id===row.dataset.rowId)?.flexOrder}));currentDraft.habits=[...document.querySelectorAll('.habit-editor')].map(row=>({id:row.dataset.rowId,full:$('[name="habit-full"]',row).value.trim(),light:$('[name="habit-light"]',row).value.trim(),reminder:$('[name="habit-reminder"]',row).value,milestoneId:$('[name="habit-milestone"]',row)?.value||'',level:$('[name="habit-level"]',row)?.value.trim()||'Level 1'}))}
function lifestyleForm(id){const h=state.lifestyle.find(r=>r.id===id);const draft=h?structuredClone(h):{id:uid(),name:'',category:'Wellbeing',frequency:'daily',days:[],values:'',habits:[{id:uid(),full:'',light:'',reminder:''}]};draft.habits=Array.isArray(draft.habits)?draft.habits:[{id:draft.id,full:draft.full||'',light:draft.light||'',reminder:draft.reminder||''}];const ritualRows=()=>draft.habits.map((item,i)=>`<div class="ritual-editor" data-row-id="${esc(item.id)}"><div class="ritual-editor-head"><strong>Habit ${i+1}</strong>${draft.habits.length>1?`<button class="text-link danger" type="button" data-remove-ritual-habit="${esc(item.id)}">Remove</button>`:''}</div><label>Locked-in habit<input name="ritual-full" maxlength="100" required value="${esc(item.full)}" placeholder="What you do when you’re locked in"></label><label>Lowkey version<input name="ritual-light" maxlength="100" required value="${esc(item.light)}" placeholder="The easiest version that still counts"></label><label>Reminder time<input type="time" name="ritual-reminder" value="${esc(item.reminder)}"></label></div>`).join('');const selectedValues=(draft.values||'').split(',').map(v=>v.trim()).filter(Boolean);const customCategory=!categories.includes(draft.category);const frequencyType=['daily','weekdays','weekends'].includes(draft.frequency)?draft.frequency:draft.days?.length?'days':draft.frequency?.includes('×')||draft.frequency?.includes('x')?'times':'custom';showDialog(`<h2>${h?'Edit your ritual':'Add a Lifestyle ritual'}</h2><p class="helper">A ritual groups habits that belong together, with no finish date.</p><form id="lifestyle-form"><label for="life-name">Ritual name</label><input id="life-name" name="name" maxlength="65" required value="${esc(draft.name)}" placeholder="e.g. Evening reset"><div class="field-pair"><label>Category<select name="category">${categories.map(c=>option(c,customCategory?'custom':draft.category)).join('')}${option('custom',customCategory?'custom':'','Custom…')}</select></label><label>Repeat<select name="frequencyType">${[['daily','Daily'],['weekdays','Weekdays'],['weekends','Weekends'],['times','Times per week'],['days','Specific days'],['custom','Custom…']].map(([v,l])=>option(v,frequencyType,l)).join('')}</select></label></div><label id="custom-category-wrap" ${customCategory?'':'hidden'}>Custom category<input name="customCategory" value="${customCategory?esc(draft.category):''}" maxlength="50" placeholder="Name your category"></label><div id="times-wrap" ${frequencyType==='times'?'':'hidden'}><label>Times per week<input name="timesPerWeek" type="number" min="1" max="7" value="${parseInt(draft.frequency)||3}"></label></div><fieldset id="days-wrap" class="weekday-picker" ${frequencyType==='days'?'':'hidden'}><legend>Choose days</legend>${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((day,i)=>`<label><input type="checkbox" name="days" value="${i}" ${(draft.days||[]).map(Number).includes(i)?'checked':''}>${day}</label>`).join('')}</fieldset><label id="custom-frequency-wrap" ${frequencyType==='custom'?'':'hidden'}>Custom repeat<input name="customFrequency" value="${frequencyType==='custom'?esc(draft.frequency):''}" maxlength="50" placeholder="e.g. every other week"></label><details class="value-picker" open><summary>Values this ritual supports ＋</summary><div class="value-choices">${valueChoices.map(v=>`<label class="check-label"><input type="checkbox" name="valuesList" value="${v}" ${selectedValues.includes(v)?'checked':''}>${v}</label>`).join('')}</div><label>Custom value<input name="customValue" placeholder="Write your own value" maxlength="50"></label></details><h3 class="form-section">Habits in this ritual</h3><div id="ritual-rows">${ritualRows()}</div><button type="button" class="text-link" id="add-ritual-habit">＋ Add another habit</button><p class="helper">Set phone alerts for each habit. Completing a task turns off that day’s alert.</p><p class="form-error" role="alert" tabindex="-1"></p><button class="button" type="submit">Save ritual</button></form>`,true);const f=$('#lifestyle-form');function readRitualRows(){draft.habits=[...f.querySelectorAll('.ritual-editor')].map(row=>({id:row.dataset.rowId,full:$('[name="ritual-full"]',row).value.trim(),light:$('[name="ritual-light"]',row).value.trim(),reminder:$('[name="ritual-reminder"]',row).value}))}function redrawRitualRows(){$('#ritual-rows').innerHTML=ritualRows()}function toggleCustom(){const type=f.elements.frequencyType.value;$('#custom-category-wrap').hidden=f.elements.category.value!=='custom';$('#times-wrap').hidden=type!=='times';$('#days-wrap').hidden=type!=='days';$('#custom-frequency-wrap').hidden=type!=='custom'}f.elements.category.onchange=toggleCustom;f.elements.frequencyType.onchange=toggleCustom;$('#add-ritual-habit').onclick=()=>{readRitualRows();draft.habits.push({id:uid(),full:'',light:'',reminder:''});redrawRitualRows()};f.addEventListener('click',e=>{const b=e.target.closest('[data-remove-ritual-habit]');if(!b)return;readRitualRows();draft.habits=draft.habits.filter(item=>item.id!==b.dataset.removeRitualHabit);redrawRitualRows()});f.onsubmit=async e=>{e.preventDefault();readRitualRows();const data=new FormData(f),type=data.get('frequencyType'),customCategory=String(data.get('customCategory')||'').trim(),customFrequency=String(data.get('customFrequency')||'').trim();draft.name=String(data.get('name')||'').trim();draft.category=data.get('category')==='custom'?customCategory:data.get('category');draft.days=data.getAll('days').map(Number);draft.frequency=type==='times'?`${data.get('timesPerWeek')||3}×/week`:type==='days'?'selected days':type==='custom'?customFrequency:type;draft.values=[...data.getAll('valuesList'),String(data.get('customValue')||'').trim()].filter(Boolean).join(', ');if(!draft.name||!draft.category||!draft.frequency||type==='days'&&!draft.days.length||!draft.habits.length||draft.habits.some(item=>!item.full||!item.light))return error(f,'Complete the ritual name, schedule, category, and both versions of every habit.');delete draft.full;delete draft.light;delete draft.reminder;const at=state.lifestyle.findIndex(r=>r.id===draft.id);if(at>=0)state.lifestyle[at]=structuredClone(draft);else state.lifestyle.push(structuredClone(draft));dialog.close();render();await save('Lifestyle ritual saved.')}}function somedayForm(){showDialog(`<h2>Save it for someday.</h2><p>Keep the dream without asking your current life to make room for it yet.</p><form id="someday-form"><label>Someday goal<input name="name" maxlength="90" required placeholder="What do you want to do someday?"></label><label>Why does it matter?<textarea name="why" maxlength="500" placeholder="A note for your future self"></textarea></label><label>Inspirations<textarea name="inspiration" maxlength="800" placeholder="Who or what inspired this dream?"></textarea></label><p class="form-error" role="alert"></p><button class="button">Save the dream</button></form>`,false,'SAVE THE SPARK');$('#someday-form').onsubmit=async e=>{e.preventDefault();const f=e.target,name=f.elements.name.value.trim();if(!name)return error(f,'Name the dream you want to keep.');state.someday.push({id:uid(),name,why:f.elements.why.value.trim(),inspiration:f.elements.inspiration.value.trim()});dialog.close();render();await save('Dream saved. No deadline needed.')}}
function affirmationForm(id=''){const old=state.affirmationSets.find(set=>set.id===id);let recordedAudio=old?.audioSrc||'';showDialog(`<h2>${old?'Shape your affirmations.':'Create an affirmation set.'}</h2><form id="affirmation-form"><label>Set name<input name="name" required maxlength="80" value="${esc(old?.name)}"></label><label>Affirmations<textarea name="affirmations" required rows="8">${esc((old?.affirmations||[]).join('\n'))}</textarea></label><section class="voice-studio"><span class="eyebrow">YOUR WORDS, YOUR FREQUENCY</span><h3>Record these in your own voice</h3><div class="inline-actions"><button type="button" class="button secondary" id="record-voice">● Start recording</button><span id="record-status">${recordedAudio?'Recording saved':'No recording yet'}</span></div><label>Background sound<select name="soundscape">${[['none','No background'],['hz528','528 Hz glow'],['bowls','Sound bowls'],['rain','Rain'],['rnb','Soft R&B beat']].map(([v,l])=>option(v,old?.soundscape||'none',l)).join('')}</select></label><p class="helper">Your voice recording stays on this device. Background sound plays with it.</p></section><details class="value-picker"><summary>Make it a ritual ＋</summary><label class="check-label affirmation-ritual-choice"><input type="checkbox" name="makeRitual" ${state.lifestyle.some(r=>r.affirmationSetId===old?.id)?'checked':''}>Practice each affirmation as its own daily habit</label><p class="helper">Every line in this set will become a habit inside one affirmation ritual.</p></details><label>Who can see this set?<select name="visibility"><option value="private">Just for me</option><option value="public" ${old?.visibility==='public'?'selected':''}>Public</option></select></label><p class="form-error" role="alert"></p><button class="button">Save affirmation set</button>${old?`<button type="button" class="button secondary" ${action('archive-affirmation',old.id)}>Archive set</button>`:''}</form>`,false,old?'EDIT YOUR SET':'A SET TO RETURN TO');const f=$('#affirmation-form'),record=$('#record-voice');record.onclick=async()=>{if(mediaRecorder?.state==='recording'){mediaRecorder.stop();record.textContent='● Start recording';return}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});audioChunks=[];mediaRecorder=new MediaRecorder(stream);mediaRecorder.ondataavailable=e=>audioChunks.push(e.data);mediaRecorder.onstop=()=>{const blob=new Blob(audioChunks,{type:mediaRecorder.mimeType});const reader=new FileReader();reader.onload=()=>{recordedAudio=reader.result;$('#record-status').textContent='Recording saved';stream.getTracks().forEach(t=>t.stop())};reader.readAsDataURL(blob)};mediaRecorder.start();record.textContent='■ Stop recording';$('#record-status').textContent='Recording…'}catch{error(f,'Microphone access is needed to record your affirmations.')}};f.onsubmit=async e=>{e.preventDefault();const data=new FormData(f),name=f.elements.name.value.trim(),affirmations=f.elements.affirmations.value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(!name||!affirmations.length)return error(f,'Name the set and add at least one affirmation.');const next={id:old?.id||uid(),name,affirmations,visibility:f.elements.visibility.value,audioSrc:recordedAudio,soundscape:f.elements.soundscape.value};if(old)Object.assign(old,next);else state.affirmationSets.unshift(next);const ritualAt=state.lifestyle.findIndex(r=>r.affirmationSetId===next.id);if(data.get('makeRitual')){const ritual={id:ritualAt>=0?state.lifestyle[ritualAt].id:uid(),affirmationSetId:next.id,name:`${name} affirmations`,category:'Affirmations',frequency:'daily',values:'Self-respect, Growth',habits:affirmations.map((line,i)=>({id:state.lifestyle[ritualAt]?.habits?.[i]?.id||uid(),full:line,light:line,reminder:''}))};if(ritualAt>=0)state.lifestyle[ritualAt]=ritual;else state.lifestyle.push(ritual)}else if(ritualAt>=0)state.lifestyle.splice(ritualAt,1);dialog.close();visionTab='affirmations';render();await save(data.get('makeRitual')?'Affirmation set saved and added to your rituals.':'Affirmation set saved.')}}
function affirmationView(id){const set=state.affirmationSets.find(item=>item.id===id);if(!set)return;showDialog(`<span class="eyebrow">${set.visibility==='public'?'PUBLIC AFFIRMATION SET':'JUST FOR ME'}</span><h2>${esc(set.name)}</h2><div class="affirmation-reading">${set.affirmations.map((line,i)=>`<p><span>${String(i+1).padStart(2,'0')}</span>${esc(line)}</p>`).join('')}</div>${set.audioSrc?`<button class="button" ${action('play-affirmation',set.id)}>▶ Play voice + ${esc(set.soundscape||'quiet')}</button>`:''}<div class="inline-actions"><button class="button secondary" ${action('edit-affirmation',set.id)}>Edit this set</button><button class="text-link" ${action('archive-affirmation',set.id)}>Archive</button></div>`,true,'WORDS TO RETURN TO')}function playAffirmation(id){const set=state.affirmationSets.find(x=>x.id===id);if(!set?.audioSrc)return;const audio=new Audio(set.audioSrc),ctx=new AudioContext(),gain=ctx.createGain();gain.gain.value=.09;gain.connect(ctx.destination);if(set.soundscape==='hz528'||set.soundscape==='bowls'){const o=ctx.createOscillator();o.frequency.value=set.soundscape==='hz528'?528:196;o.type='sine';o.connect(gain);o.start();audio.onended=()=>{o.stop();ctx.close()}}else if(set.soundscape==='rain'){const buffer=ctx.createBuffer(1,ctx.sampleRate*2,ctx.sampleRate),d=buffer.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1)*.25;const source=ctx.createBufferSource();source.buffer=buffer;source.loop=true;source.connect(gain);source.start();audio.onended=()=>{source.stop();ctx.close()}}else if(set.soundscape==='rnb'){const o=ctx.createOscillator();o.frequency.value=110;o.type='triangle';o.connect(gain);o.start();audio.onended=()=>{o.stop();ctx.close()}}audio.play()}
